197	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
198	    @Override
199	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
200	        Owner owner = this.clinicService.findOwnerById(ownerId);
201	        if (owner != null) {
202	            Pet pet = owner.getPet(petId);
203	            if (pet != null) {
204	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
205	            }
206	        }
207	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
208	    }
209	}
